    // Changelog
    'changelog.title': '변경 로그',
    'changelog.subtitle': '새로운 기능과 개선 사항을 기록해 사이트 활동성을 보여줍니다.',
    'changelog.entry1.title': '홈 페이지 개선 - 핵심 가치 제안 명확화',
    'changelog.entry1.desc': '사이트 상단에 "누구에게, 무엇을 해결해주는지" 명확한 히어로 섹션을 추가하고, 주요 특징 4가지를 눈에 띄게 배치했습니다.',
    'changelog.entry2.title': '콘텐츠 품질 체크리스트 정리',
    'changelog.entry2.desc': '정책 준수, 사용자 경험, 신뢰 요소를 스스로 점검할 수 있는 내부 체크 포인트를 추가했습니다.',
    'changelog.entry3.title': '코드 스니펫 페이지 확장',
    'changelog.entry3.desc': '언어별 예제 코드를 보강해 주요 도구 사용법을 빠르게 복기할 수 있게 했습니다.',
    'changelog.entry4.title': 'ads.txt 노출 및 소유권 검증',
    'changelog.entry4.desc': '소유권 확인을 위해 ads.txt를 루트 경로에 서빙하고, 필요한 메타 태그와 광고 스크립트를 추가했습니다.',
    'changelog.entry5.title': '다국어 지원 (한국어/영어)',
    'changelog.entry5.desc': '사이트 전체에 한국어와 영어 번역을 추가하여 글로벌 사용자도 편리하게 이용할 수 있게 했습니다.',
    'changelog.entry6.title': '정책 페이지 추가',
    'changelog.entry6.desc': '개인정보 처리방침, 이용약관, 문의 페이지를 추가하여 법적 요구사항을 충족하고 사용자 신뢰도를 높였습니다.',
    'changelog.entry7.title': 'JWT Signer 도구 추가',
    'changelog.entry7.desc': 'JWT 토큰을 디코딩하는 기능에 더해, 직접 서명하고 생성할 수 있는 JWT Signer 도구를 추가했습니다.',
    'changelog.entry8.title': 'MyBatis SQL 변환기 추가',
    'changelog.entry8.desc': 'MyBatis 쿼리에서 파라미터를 실제 값으로 치환하여 실행 가능한 SQL로 변환하는 도구를 추가했습니다.',
    'changelog.entry9.title': 'chmod 권한 계산기 & IP 계산기 추가',
    'changelog.entry9.desc': 'Linux/Unix 파일 권한 계산, IP 서브넷 계산, 진법 변환 등 시스템 관리자를 위한 도구를 추가했습니다.',
    'changelog.entry10.title': '다크 모드 자동 지원',
    'changelog.entry10.desc': '사용자의 시스템 설정에 따라 자동으로 다크 모드를 적용하여 눈의 피로를 줄이고 야간 작업을 편리하게 했습니다.',
    'changelog.entry11.title': '반응형 디자인 최적화',
    'changelog.entry11.desc': 'Mobile, Tablet, Desktop 모든 기기에서 최적화된 UI/UX를 제공하도록 반응형 디자인을 개선했습니다.',
    'changelog.entry12.title': 'SEO 최적화 및 구조화된 데이터 추가',
    'changelog.entry12.desc': 'Open Graph, Twitter Card, JSON-LD Schema를 추가하여 검색 엔진 최적화를 강화하고 sitemap/robots.txt를 생성했습니다.',

